#pragma once
#include <string>
#include <string_view>
namespace painter_body_tess {
enum class Result { Plain, Converted, Unsupported };
// Validate the non-programmable stage shape and the exact option list generated by uber_deffer.
inline Result normalize(std::string& vs,std::string& ps,int skin,std::string_view hs,std::string_view ds,
                        bool gs,bool cs,bool detailBumpBound) {
    if(gs||cs)return Result::Unsupported;
    if(hs.empty() && ds.empty())return vs.find('(')==std::string::npos && ps.find('(')==std::string::npos ? Result::Plain:Result::Unsupported;
    // any bone count a vertex: the caller keeps the pass's own count for the plain program
    if(skin<0 || skin>4 || hs.substr(0,10)!="DX11\\tess(")return Result::Unsupported;
    const auto suffix=hs.substr(9);
    if(suffix.empty() || suffix.back()!=')')return Result::Unsupported;
    if(vs!="deffer_model_bump"+std::string(suffix))return Result::Unsupported;
    const bool shadow=ps=="dumb" && ds==std::string("DX11\\tess_shadow")+std::string(suffix);
    if(!shadow && ds!=hs)return Result::Unsupported;
    const bool alpha=ps=="deffer_base_aref_bump"+std::string(suffix);
    if(!shadow && !alpha && ps!="deffer_base_bump"+std::string(suffix))return Result::Unsupported;
    std::string_view options=suffix.substr(1,suffix.size()-2);
    auto take=[&](std::string_view key){if(options.substr(0,key.size())!=key)return false;options.remove_prefix(key.size());return true;};
    const bool pn=take("TESS_PN,"),hm=take("TESS_HM,");if(!pn&&!hm)return Result::Unsupported;
    // Model programs don't export a level lightmap channel. Never map that variant to a non-LMH skinned VS.
    if(take("USE_LM_HEMI,"))return Result::Unsupported;
    const bool detail=take("USE_TDETAIL,"),detailBump=take("USE_TDETAIL_BUMP,");
    if(!options.empty())return Result::Unsupported;
    if(shadow){vs="shadow_direct_model";return Result::Converted;}
    // The plain pair: the programs this pass was compiled from, without the tessellation. Not the "-hq" pair - its
    // programs declare the steep-parallax values (m_invW, s_bumpX) a tessellated pass does not have, and the wound clone
    // then refuses it (constant_contract_changed).
    (void)detailBumpBound;
    vs=detail||detailBump?"deffer_model_bump_d":"deffer_model_bump";
    ps=alpha?"deffer_base_aref_bump":"deffer_base_bump";
    if(detail||detailBump)ps+="_d";
    return Result::Converted;
}
template<class Pass> inline Result fromPass(const Pass& p,std::string& v,std::string& f) {
    auto shaderName=[](const auto& stage)->std::string_view {return stage&&stage->sh&&stage->cName.size()?*stage->cName:"";};
    if(!p.vs||!p.ps||(p.hs&&p.hs->sh&&!p.hs->cName.size())||(p.ds&&p.ds->sh&&!p.ds->cName.size()))return Result::Unsupported;
    return normalize(v,f,p.vs->skinning,shaderName(p.hs),shaderName(p.ds),!!(p.gs&&p.gs->gs),!!(p.cs&&p.cs->sh),
                     p.constants&&p.constants->get("s_detailBump")!=nullptr);
}
template<class Pass,class Resources> inline void triangleStages(Pass& p,Resources& resources,Result result){
    if(result==Result::Converted){p.hs=resources._CreateHS("null");p.ds=resources._CreateDS("null");}
}
}
